import * as PDF from './pdf.js';
import * as Core from './core.js';
import * as Office from './office.js';
import {t} from './i18n.js';
const $=selector=>document.querySelector(selector),esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),safeName=name=>name.replace(/[\\/:*?"<>|]/g,'_').slice(0,120);
export function openExportDialog(d,{selected,modal,button,run,download,shareFile,toast,recognize}){
 if(!d.pages.length)return toast('أضف صفحة قبل التصدير');const edits=new Map();let generated=null;
 const action=button('إنشاء وتنزيل PDF',create,true);
 modal('تصدير المستند',`<div class="form-row"><label>صيغة الملف<select id="export-format"><option value="pdf">PDF</option><option value="docx">Word (.docx)</option><option value="xlsx">Excel (.xlsx)</option><option value="csv">CSV</option><option value="txt">TXT</option></select></label><label><input id="selected-export" type="checkbox" ${selected.length?'':'disabled'}> الصفحات المحددة فقط</label></div><div id="pdf-export-options"><div class="form-row"><label>حجم الصفحة<select id="export-size"><option value="a4">A4</option><option value="letter">Letter</option><option value="original">نسبة الصورة الأصلية</option></select></label><label>الاتجاه<select id="export-orientation"><option value="portrait">عمودي</option><option value="landscape">أفقي</option></select></label><label>الجودة<select id="quality"><option value="0.92">عالية</option><option value="0.75">متوسطة — ملف أصغر</option><option value="0.55">اقتصادية</option></select></label></div><label><input id="searchable-export" type="checkbox" checked> PDF قابل للبحث (للصفحات التي استُخرج نصها)</label><div class="form-row"><label>كلمة مرور PDF (اختيارية، 8 أحرف أو أكثر)<input id="pdf-password" type="password" autocomplete="new-password"></label><label>علامة مائية اختيارية<input id="watermark" maxlength="60" placeholder="بدون علامة مائية"></label></div></div><div id="word-export-options" hidden><div class="form-row"><label>محتوى Word<select id="word-mode"><option value="images">صور الصفحات — الحفاظ على الشكل</option><option value="text">نص قابل للتعديل — يحتاج OCR</option></select></label></div><p class="hint">نص Word يحافظ على المحتوى، وليس التنسيق الدقيق للصفحة المصوّرة.</p></div><div id="text-export-status" hidden><p id="export-ocr-status" class="hint"></p><button id="export-recognize" class="secondary">استخرج النص أولاً</button></div><div id="table-export-options" hidden><p class="hint">اكتشاف الجداول تقديري. راجع الخلايا وعدّلها قبل التصدير.</p><div class="form-row"><label>اختر صفحة<select id="table-page"></select></label><label>فاصل الأعمدة<select id="table-delimiter"><option value="auto">تلقائي</option><option value="tab">علامة جدولة</option><option value="comma">فاصلة</option><option value="semicolon">فاصلة منقوطة</option></select></label></div><h3>معاينة الجدول</h3><div id="table-preview" class="table-preview" data-user-content></div><div class="actions-wrap"><button id="table-add-row" class="secondary">إضافة صف</button><button id="table-add-column" class="secondary">إضافة عمود</button><button id="table-reset" class="secondary">استعادة الجدول</button></div><p class="hint">كل صفحة تصبح ورقة مستقلة في Excel. CSV يصدّر الصفحة المعروضة.</p></div><div class="actions-wrap"><button class="secondary" id="jpg-export">تنزيل JPG</button><button class="secondary" id="png-export">تنزيل PNG</button><button class="secondary" id="print-doc">طباعة</button></div><div id="share-ready"></div>`,[action]);
 const pages=()=>$('#selected-export').checked?d.pages.filter(p=>selected.includes(p.id)):d.pages;
 function currentRows(){const id=$('#table-page').value,p=pages().find(p=>p.id===id);if(!p)return[];if(!edits.has(id)&&p.ocr?.text?.trim())edits.set(id,Office.tableFromPage(p));return edits.get(id)||[];}
 function preview(){const rows=currentRows(),cols=Math.max(1,...rows.map(r=>r.length));$('#table-preview').innerHTML=rows.length?`<table><thead><tr><th></th>${Array.from({length:cols},(_,i)=>`<th>${i+1}</th>`).join('')}</tr></thead><tbody>${rows.map((r,y)=>`<tr><th>${y+1}</th>${Array.from({length:cols},(_,x)=>`<td><input dir="auto" data-row="${y}" data-col="${x}" value="${esc(r[x]||'')}" aria-label="${y+1} / ${x+1}"></td>`).join('')}</tr>`).join('')}</tbody></table>`:'';}
 function update(){const format=$('#export-format').value,needsText=format!=='pdf'&&(format!=='docx'||$('#word-mode').value==='text'),hasTable=['xlsx','csv'].includes(format),missing=pages().filter(p=>!p.ocr?.text?.trim()).length;$('#pdf-export-options').hidden=format!=='pdf';$('#word-export-options').hidden=format!=='docx';$('#text-export-status').hidden=!needsText||!missing;$('#export-ocr-status').textContent=t('استخرج النص لكل الصفحات المختارة قبل تصدير النص أو الجداول');$('#table-export-options').hidden=!hasTable;action.querySelector('span').textContent=t(format==='pdf'?'إنشاء وتنزيل PDF':'تنزيل الملف');const old=$('#table-page').value;$('#table-page').innerHTML=pages().map((p,i)=>`<option value="${esc(p.id)}">${esc(t('صفحة {n}',{n:i+1}))}</option>`).join('');if(pages().some(p=>p.id===old))$('#table-page').value=old;for(const id of ['table-add-row','table-add-column','table-reset'])$('#'+id).disabled=!currentRows().length;if(hasTable)preview();generated=null;$('#share-ready').replaceChildren();}
 function create(){const format=$('#export-format').value,chosen=pages();if(!chosen.length)return toast('أضف صفحة قبل التصدير');const options={size:$('#export-size').value,landscape:$('#export-orientation').value==='landscape',quality:Number($('#quality').value),searchable:$('#searchable-export').checked,watermark:$('#watermark').value.trim(),password:$('#pdf-password').value,title:d.name};const mode=$('#word-mode').value;
  if(format!=='pdf'&&(format!=='docx'||mode==='text')){try{Office.textPages(format==='csv'?chosen.filter(p=>p.id===$('#table-page').value):chosen);}catch(e){toast(e.message);return;}}
  // Snapshot inputs before processing; table edits made later cannot alter an in-flight export.
  const tables=['xlsx','csv'].includes(format)?(format==='csv'?chosen.filter(p=>p.id===$('#table-page').value):chosen).map(p=>({id:p.id,rows:(edits.get(p.id)||Office.tableFromPage(p)).map(r=>[...r]),rtl:Office.isRtl(p.ocr.text)})):[];const csvId=$('#table-page').value;
  run('تجهيز الملف…',async()=>{let blob;if(format==='pdf'){blob=await PDF.searchablePdf(chosen,options);if(options.password)blob=await PDF.encryptPdf(blob,options.password);}else if(format==='docx')blob=await Office.wordDocument(chosen,{mode,title:d.name,landscape:options.landscape});else if(format==='xlsx')blob=Office.excelDocument(tables);else if(format==='csv')blob=Office.csvDocument(tables.find(p=>p.id===csvId)?.rows||[]);else if(format==='txt')blob=Office.plainDocument(chosen);else throw Error('صيغة تصدير غير مدعومة');generated=blob;const name=safeName(d.name)+'.'+format;download(blob,name);$('#share-ready')?.replaceChildren(button('مشاركة الملف الجاهز',()=>shareFile(blob,name),true));toast('الملف جاهز');});
 }
 $('#export-format').onchange=update;$('#word-mode').onchange=update;$('#selected-export').onchange=update;$('#export-recognize').onclick=recognize;
 $('#table-page').onchange=()=>{preview();for(const id of ['table-add-row','table-add-column','table-reset'])$('#'+id).disabled=!currentRows().length;};$('#table-delimiter').onchange=()=>{const p=pages().find(p=>p.id===$('#table-page').value);if(p?.ocr?.text){edits.set(p.id,$('#table-delimiter').value==='auto'?Office.tableFromPage(p):Office.parseTable(p.ocr.text,$('#table-delimiter').value));preview();}};
 $('#table-preview').oninput=e=>{const input=e.target;if(input.dataset.row!==undefined){const rows=currentRows();rows[Number(input.dataset.row)][Number(input.dataset.col)]=input.value;}};
 $('#table-add-row').onclick=()=>{const rows=currentRows();rows.push(Array(Math.max(1,...rows.map(r=>r.length))).fill(''));preview();};$('#table-add-column').onclick=()=>{const rows=currentRows(),width=Math.max(1,...rows.map(r=>r.length))+1;rows.forEach(r=>{while(r.length<width)r.push('');});preview();};$('#table-reset').onclick=()=>{edits.delete($('#table-page').value);preview();};
 for(const kind of ['jpg','png'])$('#'+kind+'-export').onclick=()=>run('تصدير الصور…',async()=>{for(const [i,p]of pages().entries()){const bitmap=await Core.image(p.blob),c=Core.makeCanvas(bitmap.width,bitmap.height);c.getContext('2d').drawImage(bitmap,0,0);bitmap.close();download(await Core.toBlob(c,kind==='png'?'image/png':'image/jpeg'),`${safeName(d.name)}-${i+1}.${kind}`);}});
 $('#print-doc').onclick=()=>{const urls=pages().map(p=>URL.createObjectURL(p.blob)),win=window.open('','_blank');if(!win)return toast('اسمح بفتح نافذة للطباعة');win.document.write(`<!doctype html><html><head><title>${esc(d.name)}</title><style>@page{size:A4;margin:10mm}img{display:block;width:100%;height:270mm;object-fit:contain;break-after:page}img:last-child{break-after:auto}</style></head><body>${urls.map(u=>`<img src="${u}" alt="Page">`).join('')}</body></html>`);win.document.close();win.onload=()=>win.print();win.onafterprint=()=>urls.forEach(u=>URL.revokeObjectURL(u));};update();
}
